-- Grants: deny by default, one table (or schema) to one role per statement, no default privileges,
-- so a table added later is unreachable until its own migration grants it. USAGE only: neither app
-- role creates in schema billing.
GRANT USAGE ON SCHEMA billing TO app_runtime;--> statement-breakpoint
GRANT USAGE ON SCHEMA billing TO app_system;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON TABLE billing.payments TO app_runtime;--> statement-breakpoint
-- Reconciliation R3 (ledgerReconciliation.listSucceededPayments, spec §9 item 9) reads the paid
-- payments of every tenant: SELECT only, and no policy (BYPASSRLS skips them).
GRANT SELECT ON TABLE billing.payments TO app_system;--> statement-breakpoint
GRANT SELECT, INSERT ON TABLE billing.stripe_events TO app_runtime;--> statement-breakpoint
-- The Stripe events system methods: user-less (platform) events, the lookup and the purge.
GRANT SELECT, INSERT, DELETE ON TABLE billing.stripe_events TO app_system;--> statement-breakpoint
-- Outbox: the runtime role is insert-only (no SELECT: its inserts carry no RETURNING); app_system
-- polls, marks, purges and writes the platform-tenant rows through the pinned outbox.* methods.
GRANT INSERT ON TABLE billing.outbox TO app_runtime;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE billing.outbox TO app_system;--> statement-breakpoint
-- Ledger: neither app role updates or deletes a tenant table (entry refs and discrepancies are
-- append-only); app_runtime gets nothing on the two local tables, which app_system also updates.
GRANT SELECT, INSERT ON TABLE billing.ledger_accounts TO app_runtime;--> statement-breakpoint
GRANT SELECT, INSERT ON TABLE billing.ledger_accounts TO app_system;--> statement-breakpoint
GRANT SELECT, INSERT ON TABLE billing.ledger_entry_refs TO app_runtime;--> statement-breakpoint
GRANT SELECT, INSERT ON TABLE billing.ledger_entry_refs TO app_system;--> statement-breakpoint
GRANT SELECT, INSERT ON TABLE billing.ledger_discrepancies TO app_runtime;--> statement-breakpoint
GRANT SELECT, INSERT ON TABLE billing.ledger_discrepancies TO app_system;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON TABLE billing.ledger_reconciliation_runs TO app_system;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON TABLE billing.ledger_trusted_state TO app_system;--> statement-breakpoint
-- Policies: row-local, calling the platform helpers (platform 0002_rls_helpers) directly, never
-- through a subquery (Citus rejects them). Rows with tenant_id = PLATFORM_TENANT_ID match no runtime
-- policy (app.tenant_id() is never the nil UUID): only app_system (BYPASSRLS) reads or writes them.
-- A member reads its own payments in the active tenant; elevation (billing:read-all) reads the
-- tenant's. Writes stay the member's own: elevation reads, it never writes another member's payment.
CREATE POLICY payments_select ON billing.payments FOR SELECT TO app_runtime
  USING (tenant_id = app.tenant_id() AND (user_id = app.user_id() OR app.elevated()));--> statement-breakpoint
CREATE POLICY payments_insert ON billing.payments FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY payments_update ON billing.payments FOR UPDATE TO app_runtime
  USING (tenant_id = app.tenant_id() AND user_id = app.user_id())
  WITH CHECK (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
-- The webhook records an event as the owner in the signed metadata; user-less (platform) events go
-- through the system pool. No UPDATE or DELETE for the runtime role (no grant either).
CREATE POLICY stripe_events_select ON billing.stripe_events FOR SELECT TO app_runtime
  USING (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY stripe_events_insert ON billing.stripe_events FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id() AND user_id = app.user_id());--> statement-breakpoint
CREATE POLICY outbox_insert ON billing.outbox FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id());--> statement-breakpoint
-- Ledger reads need elevation (the consumer's `roles: []` principal never has it); inserts only the
-- own tenant. No UPDATE or DELETE policy (and no grant): denied.
CREATE POLICY ledger_accounts_select ON billing.ledger_accounts FOR SELECT TO app_runtime
  USING (tenant_id = app.tenant_id() AND app.elevated());--> statement-breakpoint
CREATE POLICY ledger_accounts_insert ON billing.ledger_accounts FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id());--> statement-breakpoint
CREATE POLICY ledger_entry_refs_select ON billing.ledger_entry_refs FOR SELECT TO app_runtime
  USING (tenant_id = app.tenant_id() AND app.elevated());--> statement-breakpoint
CREATE POLICY ledger_entry_refs_insert ON billing.ledger_entry_refs FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id());--> statement-breakpoint
CREATE POLICY ledger_discrepancies_select ON billing.ledger_discrepancies FOR SELECT TO app_runtime
  USING (tenant_id = app.tenant_id() AND app.elevated());--> statement-breakpoint
CREATE POLICY ledger_discrepancies_insert ON billing.ledger_discrepancies FOR INSERT TO app_runtime
  WITH CHECK (tenant_id = app.tenant_id());
